33	static int configure(struct flb_out_lib_config *ctx,
34	                     struct flb_output_instance *ins)
35	{
36	    const char *tmp;
37	
38	    tmp = flb_output_get_property("format", ins);
39	    if (!tmp) {
40	        ctx->format = FLB_OUT_LIB_FMT_MSGPACK;
41	    }
42	    else {
43	        if (strcasecmp(tmp, FLB_FMT_STR_MSGPACK) == 0) {
44	            ctx->format = FLB_OUT_LIB_FMT_MSGPACK;
45	        }
46	        else if (strcasecmp(tmp, FLB_FMT_STR_JSON) == 0) {
47	            ctx->format = FLB_OUT_LIB_FMT_JSON;
48	        }
49	    }
50	
51	    tmp = flb_output_get_property("max_records", ins);
52	    if (tmp) {
53	        ctx->max_records = atoi(tmp);
54	    }
55	    else {
56	        ctx->max_records = 0;
57	    }
58	
59	    return 0;
60	}
61	
62	
63	/**
64	 * User callback is passed from flb_output(ctx, output, callback)
65	 *
66	 *  The prototype of callback should be
67	 *   int (*callback)(void* data, size_t size );
68	 *    @param   data  The data which comes from input plugin.
69	 *    @param   size  The size of data.
70	 *    @return  success ? 0 : negative value
71	 *
72	 */
73	static int out_lib_init(struct flb_output_instance *ins,
74	                        struct flb_config *config,
75	                        void *data)
76	{
77	    struct flb_out_lib_config *ctx = NULL;
78	    struct flb_lib_out_cb *cb_data = data;
79	    (void) config;
80	
81	    ctx = flb_calloc(1, sizeof(struct flb_out_lib_config));
82	    if (ctx == NULL) {
83	        flb_errno();
84	        return -1;
85	    }
86	    ctx->ins = ins;
87	
88	    if (cb_data) {
89	        /* Set user callback and data */
90	        ctx->cb_func = cb_data->cb;
91	        ctx->cb_data = cb_data->data;
92	    }
93	    else {
94	        flb_plg_error(ctx->ins, "Callback is not set");
95	        flb_free(ctx);
96	        return -1;
97	    }
98	
99	    configure(ctx, ins);
100	    flb_output_set_context(ins, ctx);
101	
102	    return 0;
103	}
104	
105	static void out_lib_flush(struct flb_event_chunk *event_chunk,
106	                          struct flb_output_flush *out_flush,
107	                          struct flb_input_instance *i_ins,
108	                          void *out_context,
109	                          struct flb_config *config)
110	{
111	    int len;
112	    int count = 0;
113	    size_t off = 0;
114	    size_t last_off = 0;
115	    size_t data_size = 0;
116	    size_t alloc_size = 0;
117	    size_t out_size = 0;
118	    char *buf = NULL;
119	    char *out_buf = NULL;
120	    char *data_for_user = NULL;
121	    msgpack_object *obj;
122	    msgpack_unpacked result;
123	    struct flb_time tm;
124	    struct flb_out_lib_config *ctx = out_context;
125	    (void) i_ins;
126	    (void) config;
127	
128	    msgpack_unpacked_init(&result);
129	    while (msgpack_unpack_next(&result,
130	                               event_chunk->data,
131	                               event_chunk->size, &off) == MSGPACK_UNPACK_SUCCESS) {
132	        if (ctx->max_records > 0 && count >= ctx->max_records) {
133	            break;
134	        }
135	        switch(ctx->format) {
136	        case FLB_OUT_LIB_FMT_MSGPACK:
137	            alloc_size = (off - last_off);
138	
139	            /* copy raw bytes */
140	            data_for_user = flb_malloc(alloc_size);
141	            if (!data_for_user) {
142	                flb_errno();
143	                msgpack_unpacked_destroy(&result);
144	                FLB_OUTPUT_RETURN(FLB_ERROR);
145	            }
146	
147	            memcpy(data_for_user,
148	                   (char *) event_chunk->data + last_off, alloc_size);
149	            data_size = alloc_size;
150	            break;
151	        case FLB_OUT_LIB_FMT_JSON:
152	#ifdef FLB_HAVE_METRICS
153	            if (event_chunk->type == FLB_EVENT_TYPE_METRICS) {
154	                alloc_size = (off - last_off) + 4096;
155	                buf = flb_msgpack_to_json_str(alloc_size, &result.data);
156	                if (buf == NULL) {
157	                    msgpack_unpacked_destroy(&result);
158	                    FLB_OUTPUT_RETURN(FLB_ERROR);
159	                }
160	                data_size = strlen(buf);
161	                data_for_user = buf;
162	            }
163	            else {
164	#endif
165	            /* JSON is larger than msgpack */
166	            alloc_size = (off - last_off) + 128;
167	
168	            flb_time_pop_from_msgpack(&tm, &result, &obj);
169	            buf = flb_msgpack_to_json_str(alloc_size, obj);
170	            if (!buf) {
171	                msgpack_unpacked_destroy(&result);
172	                FLB_OUTPUT_RETURN(FLB_ERROR);
173	            }
174	
175	            len = strlen(buf);
176	            out_size = len + 32;
177	            out_buf = flb_malloc(out_size);
178	            if (!out_buf) {
179	                flb_errno();
180	                msgpack_unpacked_destroy(&result);
181	                FLB_OUTPUT_RETURN(FLB_ERROR);
182	            }
183	
184	            len = snprintf(out_buf, out_size, "[%f,%s]",
185	                           flb_time_to_double(&tm),
186	                           buf);
187	            flb_free(buf);
188	            data_for_user = out_buf;
189	            data_size = len;
190	#ifdef FLB_HAVE_METRICS
191	            }
192	#endif
193	            break;
194	        }
195	
196	        /* Invoke user callback */
197	        ctx->cb_func(data_for_user, data_size, ctx->cb_data);
198	        last_off = off;
199	        count++;
200	    }
201	
202	    msgpack_unpacked_destroy(&result);
203	    FLB_OUTPUT_RETURN(FLB_OK);
204	}
205	
206	static int out_lib_exit(void *data, struct flb_config *config)
207	{
208	    struct flb_out_lib_config *ctx = data;
209	
210	    flb_free(ctx);
211	    return 0;
212	}
213	
