78	/* Callback to check expected results */
79	static int cb_check_result_json(void *record, size_t size, void *data)
80	{
81	    char *p;
82	    char *expected;
83	    char *result;
84	    int num = get_output_num();
85	
86	    set_output_num(num+1);
87	
88	    expected = (char *) data;
89	    result = (char *) record;
90	
91	    p = strstr(result, expected);
92	    TEST_CHECK(p != NULL);
93	
94	    if (p==NULL) {
95	        flb_error("Expected to find: '%s' in result '%s'",
96	                  expected, result);
97	    }
98	    /*
99	     * If you want to debug your test
100	     *
101	     * printf("Expect: '%s' in result '%s'", expected, result);
102	     */
103	    flb_free(record);
104	    return 0;
105	}
