107	struct http_client_ctx* http_client_ctx_create()
108	{
109	    struct http_client_ctx *ret_ctx = NULL;
110	    struct mk_event_loop *evl = NULL;
111	
112	    ret_ctx = flb_calloc(1, sizeof(struct http_client_ctx));
113	    if (!TEST_CHECK(ret_ctx != NULL)) {
114	        flb_errno();
115	        TEST_MSG("flb_calloc(http_client_ctx) failed");
116	        return NULL;
117	    }
118	
119	    evl = mk_event_loop_create(16);
120	    if (!TEST_CHECK(evl != NULL)) {
121	        TEST_MSG("mk_event_loop failed");
122	        flb_free(ret_ctx);
123	        return NULL;
124	    }
125	    ret_ctx->evl = evl;
126	    flb_engine_evl_init();
127	    flb_engine_evl_set(evl);
128	
129	    ret_ctx->config = flb_config_init();
130	    if(!TEST_CHECK(ret_ctx->config != NULL)) {
131	        TEST_MSG("flb_config_init failed");
132	        mk_event_loop_destroy(evl);
133	        flb_free(ret_ctx);
134	        return NULL;
135	    }
136	
137	    ret_ctx->u = flb_upstream_create(ret_ctx->config, "127.0.0.1", PORT_OTEL, 0, NULL);
138	    if (!TEST_CHECK(ret_ctx->u != NULL)) {
139	        TEST_MSG("flb_upstream_create failed");
140	        flb_config_exit(ret_ctx->config);
141	        mk_event_loop_destroy(evl);
142	        flb_free(ret_ctx);
143	        return NULL;
144	    }
145	
146	    ret_ctx->u_conn = flb_upstream_conn_get(ret_ctx->u);
147	    TEST_CHECK(ret_ctx->u_conn != NULL);
148	
149	    ret_ctx->u_conn->upstream = ret_ctx->u;
150	
151	    return ret_ctx;
152	}
