219	void flb_test_otel_logs()
220	{
221	    struct flb_lib_out_cb cb_data;
222	    struct test_ctx *ctx;
223	    struct flb_http_client *c;
224	    int ret;
225	    int num;
226	    size_t b_sent;
227	
228	    char *buf = TEST_MSG_OTEL_LOGS;
229	
230	    clear_output_num();
231	
232	    cb_data.cb = cb_check_result_json;
233	    cb_data.data = TEST_CB_MSG_OTEL_LOGS;
234	
