+static int process_payload_traces(struct flb_opentelemetry *ctx, struct http_conn *conn,
+                                  flb_sds_t tag,
+                                  size_t tag_len,
+                                  struct mk_http_session *session,
+                                  struct mk_http_request *request)
+{
