+
+    if (ctx->raw_traces) {
+        result = process_payload_raw_traces(ctx, conn, tag, tag_len, session, request);
+    }
+    else {
+        result = process_payload_traces_proto(ctx, conn, tag, tag_len, session, request);
+    }
+
+    return result;
+}
