+int opentelemetry_prot_handle_error(struct flb_opentelemetry *ctx, struct http_conn *conn,
+                                    struct mk_http_session *session,
+                                    struct mk_http_request *request)
+{
+    send_response(conn, 400, "error: invalid request\n");
+    return -1;
+}
